function resultingString(s) {
  const stack = [];
  for (const ch of s) {
    if (stack.length > 0) {
      const gap = Math.abs(stack[stack.length - 1].charCodeAt(0) - ch.charCodeAt(0));
      if (gap === 1 || gap === 25) {
        stack.pop();
        continue;
      }
    }
    stack.push(ch);
  }
  return stack.join('');
}

