function resultingString(s) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const after = c => alphabet[(alphabet.indexOf(c) + 1) % 26];
  let current = s;
  for (;;) {
    let found = -1;
    for (let i = 0; i + 1 < current.length; i++) {
      if (after(current[i]) === current[i + 1] || after(current[i + 1]) === current[i]) { found = i; break; }
    }
    if (found === -1) return current;
    current = current.slice(0, found) + current.slice(found + 2);
  }
}

