function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(9000, 10000) : int(1, 10);
  // A short run of the alphabet (sometimes across z and a) makes removals frequent; sometimes use all 26 letters.
  const start = int(0, 25);
  const width = rand() < 0.25 ? 26 : int(1, 5);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + (start + int(0, width - 1)) % 26);
  return [s];
}
